/// <summary>
/// CB175-SalesConfirmation
/// Extension of class <c>SalesConfirmDP</c>
/// </summary>
[ExtensionOf(classStr(SalesConfirmDP))]
internal final class METSalesConfirmDP_Extension
{
}

Method.Source:
    /// <summary>
    /// CB175-SalesConfirmation
    /// Initializes a sales order confirmation header.
    /// </summary>
    /// <returns>
    /// The initialized <c>SalesConfirmHeaderTmp</c> sales order confirmation header record.
    /// </returns>
    protected SalesConfirmHeaderTmp initializeSalesOrderConfirmationHeader()
    {
        #ISOCountryRegionCodes
        #PrintMgmtSetup

        SysDocuBrandDetails docuBrandDetails;
        CompanyInfo           companyInfo           = CompanyInfo::find();
        SalesConfirmHeaderTmp salesConfirmHeaderTmp = next initializeSalesOrderConfirmationHeader();
        SalesTable            salesTable            = SalesTable::find(salesConfirmHeaderTmp.SalesId);
        METIndustryKeyTable   industryKey           = METIndustryKeyTable::find(METCustTable::find(salesTable.CustAccount).IndustryKey);
        
        SalesConfirmContract salesConfirmContract = this.parmSalesConfirmContract();
        SRSCatalogItemName name = salesConfirmContract.parmMetcashReportName();

        container reportDesignNameContainer = SrsReportRunUtil::getReportAndDesignName(name);

        select firstonly docuBrandDetails
            where docuBrandDetails.ReportName ==  conPeek(reportDesignNameContainer, 1)
                && docuBrandDetails.METIndustryKey == industryKey.IndustryKey;

        if (docuBrandDetails)
        {
            salesConfirmHeaderTmp.CompanyLogo     = SysDocuBrandImages::getImage(docuBrandDetails.Image1Name);
            salesConfirmHeaderTmp.CompanyName     = industryKey.IndustryChannel;
            salesConfirmHeaderTmp.CompanyCoRegNum = docuBrandDetails.METTaxRegNumber;
            salesConfirmHeaderTmp.CompanyPhone    = docuBrandDetails.Phone;
            salesConfirmHeaderTmp.METSiteAddress  = docuBrandDetails.displayAddress();
            salesConfirmHeaderTmp.METSalesOrderConfirmFormNotes = docuBrandDetails.METReportNotes;
        }

        salesConfirmHeaderTmp.CompanyEmail           = companyInfo.email();
        salesConfirmHeaderTmp.METCustAccount         = salesTable.CustAccount;
        salesConfirmHeaderTmp.METContactPersonId     = salesTable.contactPersonName();
        salesConfirmHeaderTmp.METOrderDiscount       = salesConfirmHeaderTmp.TotalTaxBaseAmount * salesTable.DiscPercent /100;
        salesConfirmHeaderTmp.METSalesOrderType      = salesTable.METSalesOrderType;
        salesConfirmHeaderTmp.METCustName            = salesTable.customerName();
        salesConfirmHeaderTmp.METSalesOrderDate      = DateTimeUtil::date(salesTable.CreatedDateTime);
        salesConfirmHeaderTmp.METSOCreateTime        = time2Str(DateTimeUtil::time(this.parmCustConfirmJour().CreatedDateTime), TimeSeparator::Colon, TimeFormat::AMPM);
        salesConfirmHeaderTmp.METSOConfirmCreateTime = time2Str(DateTimeUtil::time(this.parmCustConfirmJour().CreatedDateTime), TimeSeparator::Colon, TimeFormat::AMPM);
        salesConfirmHeaderTmp.METEntityId            = strUpr(curExt());
        salesConfirmHeaderTmp.ConfirmDate            = DateTimeUtil::date(this.parmCustConfirmJour().CreatedDateTime);

        return salesConfirmHeaderTmp;
    }

    /// <summary>
    /// CB175-SalesConfirmation
    /// Initializes a sales order confirmation line.
    /// </summary>
    /// <param name = "_salesConfirmHeaderTmp">
    /// A <c>SalesConfirmHeaderTmp</c> record which is the sales order confirmation header.
    /// </param>
    /// <param name = "_confirmationLineSelection">
    /// A <c>SalesConfirmDPConfirmationLineQuerySelection</c> object which the sales order confirmation line should be initialized from.
    /// </param>
    /// <returns>
    /// The initialized <c>SalesConfirmDetailsTmp</c> sales order confirmation line record.
    /// </returns>
    protected SalesConfirmDetailsTmp initializeSalesOrderConfirmationLine(
        SalesConfirmHeaderTmp                           _salesConfirmHeaderTmp,
        SalesConfirmDPConfirmationLineQuerySelection    _confirmationLineSelection)
    {
        SalesConfirmDetailsTmp  salesConfirmTmp;
        SalesQty                reserveQty;
        
        CustConfirmTrans        custConfirmTrans = _confirmationLineSelection.parmCustConfirmTrans();
        SalesLine               SalesLine        = custConfirmTrans.salesLine();
        METSalesLine            METSalesLine     = METSalesLine::find(SalesLine.RecId);

        salesConfirmTmp = next initializeSalesOrderConfirmationLine(_salesConfirmHeaderTmp, _confirmationLineSelection);
       
        if (METSalesLine.SubstitutionType == METSalesItemSubstitutionType::AlternateSuggestion)
        {
            salesConfirmTmp.METSubstituteOriginalItemID     = METSalesLine.SubstituteOriginalItemID;
            salesConfirmTmp.METSubstituteOriginalItemName   = salesLine.inventTable().productName(SystemParameters::getSystemLanguageId());
            salesConfirmTmp.METItemStatus                   = custConfirmTrans.METReasonId;
            salesConfirmTmp.METSubstituteAlternateItemID    = METSalesLine.SubstituteItemID;
            salesConfirmTmp.METSubstituteAlternateItemName  = InventTable::find(METSalesLine.SubstituteItemID).productName(SystemParameters::getSystemLanguageId());
            
        }

        salesConfirmTmp.METLineNo              = real2int(custConfirmTrans.LineNum);
        salesConfirmTmp.Name                   = SalesLine.itemName();
        salesConfirmTmp.METBarCode             = SalesLine.BarCode;
        salesConfirmTmp.METIndicators          = custConfirmTrans.METIndicators;
        salesConfirmTmp.METReasonId            = custConfirmTrans.METReasonId;
        salesConfirmTmp.METCustAvailDate       = custConfirmTrans.METCustAvailDate;
        reserveQty                             = abs(SalesLine.reservedPhysical()) + abs(SalesLine.pickedInTotalInventUnit());
        
        TmpTaxWorkTrans tmpTaxWorkTrans;
        SalesTotals salesTotals = SalesTotals::construct(salesLine.salesTable());
        salesTotals.calc();
        tmpTaxWorkTrans.setTmpData(salesTotals.tax().tmpTaxWorkTrans());

        METLegalEntityType metLegalEntityType = CompanyInfo::find().METLegalEntityType;

        //if (metLegalEntityType != METLegalEntityType::None)
        //{
        //    salesConfirmTmp.TaxAmount = 0;
        //}
		
        while select tmpTaxWorkTrans
            where tmpTaxWorkTrans.InventTransId == salesLine.InventTransId
        {
            if ((strScan(tmpTaxWorkTrans.TaxCode, METConstants::TaxCodeWEG, 1, strLen(tmpTaxWorkTrans.TaxCode))) || 
                (strScan(tmpTaxWorkTrans.TaxCode, METConstants::TaxCodeGST, 1, strLen(tmpTaxWorkTrans.TaxCode))))
            {
                if (!salesConfirmTmp.TaxAmount)
                {
                    salesConfirmTmp.TaxAmount = abs(tmpTaxWorkTrans.SourceRegulateAmountCur);
                }
                else
                {
                    salesConfirmTmp.TaxAmount = salesConfirmTmp.TaxAmount + abs(tmpTaxWorkTrans.SourceRegulateAmountCur);
                }
            }
            else if (strScan(tmpTaxWorkTrans.TaxCode, METConstants::TaxCodeWET, 1, strLen(tmpTaxWorkTrans.TaxCode)) && metLegalEntityType == metLegalEntityType::Liquor)
            {
                if (!salesConfirmTmp.METWetAmount)
                {
                    salesConfirmTmp.METWetAmount = abs(tmpTaxWorkTrans.SourceRegulateAmountCur);
                }
                else
                {
                    salesConfirmTmp.METWetAmount = salesConfirmTmp.METWetAmount + abs(tmpTaxWorkTrans.SourceRegulateAmountCur);
                }
                 
            }
        }

        if (metLegalEntityType == metLegalEntityType::Food)
        {
            salesConfirmTmp.METTotalPriceExclGST = salesLine.SalesPrice;
            salesConfirmTmp.METTotalPriceIncGST = salesConfirmTmp.TaxAmount + salesConfirmTmp.METTotalPriceExclGST;
        }
        else if (metLegalEntityType == metLegalEntityType::Liquor)
        {
            salesConfirmTmp.METTotalPriceExclGST = salesLine.SalesPrice;
            salesConfirmTmp.METWetAmount         = salesConfirmTmp.METWetAmount;
            salesConfirmTmp.METTotalPriceIncGST  = salesConfirmTmp.METTotalPriceExclGST + salesConfirmTmp.METWetAmount + salesConfirmTmp.TaxAmount;
        }
        
        salesConfirmTmp.Qty          = custConfirmTrans.Qty;
        salesConfirmTmp.METSupplyQty = custConfirmTrans.METSuppliedQty;
        salesConfirmTmp.METRebate     = this.getSalesLinePriceComponent(salesLine.InventTransId, true);
        salesConfirmTmp.METRebateFees = MarkupTrans::findValue(tableNum(CustConfirmTrans), custConfirmTrans.RecId).CalculatedAmount;
        salesConfirmTmp.SalesPrice    = this.getSalesLinePriceComponent(salesLine.InventTransId, false);
        
        if (SalesLine.PdsCWQty)
        {
            salesConfirmTmp.METTotalCartonsSupplied    = abs(SalesLine.pdsCWPickedInTotal()) + abs(SalesLine.pdsCWReservedPhysical());
            salesConfirmTmp.METTotalCartonsAdded       = abs(SalesLine.PdsCWQty);
        }
        else
        {
            salesConfirmTmp.METTotalCartonsSupplied    = abs(SalesLine.pickedInTotalSalesUnit()) + abs(SalesLine.reservedPhysicalInSalesUnit());
            salesConfirmTmp.METTotalCartonsAdded       = salesConfirmTmp.Qty;
        }

        if (strFind(metsalesLine.Indicators, METConstants::PromotionInd, 1, strLen(metsalesLine.Indicators)))
        {
            salesConfirmTmp.METIsPromotionInd  = NoYes::Yes;
        }
        
        return salesConfirmTmp;
    }

    /// <summary>
    /// CB175-SalesConfirmation
    /// Get SalesLine Price Component using InventTransId
    /// </summary>
    /// <param name = "_inventTransId">sales line inventTransId</param>
    /// <param name = "_includeInRebatesOrFees">true or false</param>
    /// <returns>value</returns>
    private Amount getSalesLinePriceComponent(InventTransId _inventTransId, boolean _includeInRebatesOrFees)
    {
        METComponentCode            metComponentCode;
        METSalesLinePriceComponent  metSalesLinePriceComponent;

        if (_includeInRebatesOrFees)
        {
            select InventTransId, sum(value) from metSalesLinePriceComponent
                group by InventTransId
                join metComponentCode
                    where metSalesLinePriceComponent.Component == metComponentCode.Component
                    && metSalesLinePriceComponent.InventTransId == _inventTransId
                    && metComponentCode.IncludeInRebatesOrFees == _includeInRebatesOrFees;
        }
        else
        {
            select InventTransId, sum(value) from metSalesLinePriceComponent
                group by InventTransId
                join metComponentCode
                    where metSalesLinePriceComponent.Component == metComponentCode.Component
                    && metSalesLinePriceComponent.InventTransId == _inventTransId
                    && metComponentCode.IncludeInCostOrBaseCost == NoYes::Yes;
        }

        return metSalesLinePriceComponent.Value;
            
    }
